A.claims=json.loads((ex/'claims/canonical_claim_ledger.json').read_text())['claims']
A.items=json.loads((ex/'learning-items/topic_3_items.json').read_text())['items']
for item in A.items:
 if item['item_id']=='ITEM-6116-3-159-SYNTH':
  item['prompt']='Describe a complete investigation of how onion epidermis cells respond to a range of salt concentrations, using a light microscope.'
  stamp(item)
 if item['item_id']=='ITEM-6116-3-P03':
  item['prompt']=item['prompt'].replace(' One cylinder was used at each concentration.','')
  assert 'One cylinder was used' not in item['prompt']
  item['canonical_answer']=item['canonical_answer'].replace('so the solution matching the cell contents lies between them.','so the solution matching the cell contents lies between them, because no change in mass occurs where the solution matches the cell contents.')
  assert 'no change in mass occurs' in item['canonical_answer']
  ans=item['canonical_answer'];k=ans.index('(e)')
  item['canonical_answer']=ans[:k]+'(e) Surface solution may not be blotted off equally from every cylinder, so some masses include liquid the cells did not take up; blot each cylinder in the same way, for example rolling it once on a paper towel. Other creditable errors are cylinders not removed after exactly 30 minutes (time each one with a stopwatch) or each concentration tested only once (repeat it and calculate a mean).'
  item['marking_guidance']=[g if not g.startswith('(e)') else '(e) 2 marks: 1 mark for a source of error, such as unequal blotting of surface solution, inexact timing or no repeats; 1 mark for an improvement that deals with that error, such as blotting each cylinder the same way, timing with a stopwatch or repeating each concentration and calculating a mean.' for g in item['marking_guidance']]
  assert any(g.startswith('(e) 2 marks: 1 mark for a source of error, such as unequal') for g in item['marking_guidance'])
  stamp(item)
for p in (ex/'content-units').glob('*.json'):
 u=json.loads(p.read_text())
 if u['unit_id']=='CU-6116-3.3.3':
  for b in u['blocks']:
   if 'water also passes through water channel proteins' in b['text']:
    b['text']=b['text'].replace('water also passes through water channel proteins','none needed')
    h=stamp(b);h.pop('qa_status')
 # The section-purpose block is dropped so the notes overview is not built from two units only.
 u['blocks']=[b for b in u['blocks'] if b['block_type']!='learner_objective']
 for b in u['blocks']:
  if b['heading']=='Active transport':
   b['heading']='What active transport is';h=stamp(b);h.pop('qa_status')
 u['title']={'CU-6116-3.3.2':'3.3.2 Osmosis','CU-6116-3.3.3':'3.3.3 Active transport'}[u['unit_id']]
 u['word_count']=sum(len(b['text'].split()) for b in u['blocks'])
 A.prebuilt_units[u['unit_id']]=u
 for o in u['objective_ids']:
  cs=[c['claim_id'] for c in A.claims if o in c['objective_ids']]
